// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadPaytone = makeLoadFont('PaytoneOne');

// Module-level font loading — delayRender/continueRender handled internally by loadFont()
const { fontFamily: paytoneFamily } = loadPaytone();



export type Sleep3DZsProps = Record<string, any>;

// Inner component for individual "Z"
const SingleZ: React.FC<{
  delay: number;
  lifespan: number;
  zColor: string;
  shadowColor: string;
  baseSize: number;
  startX: number;
  startY: number;
  swayAmount: number;
  depth: number;
  index: number;
}> = ({
  delay,
  lifespan,
  zColor,
  shadowColor,
  baseSize,
  startX,
  startY,
  swayAmount,
  depth,
  index,
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const localFrame = frame - delay;
  
  // Return early if this specific Z hasn't spawned yet or has already faded out
  if (localFrame < 0 || localFrame > lifespan) {
    return null;
  }

  const progress = localFrame / lifespan;

  // Utilize Remotion's deterministic random() for organic variations per Z
  const randomSeed = random(`seed-${index}`);
  const swayFreq = 1 + randomSeed; // Between 1 to 2 full wave cycles
  const swayAmp = swayAmount * (0.8 + 0.4 * random(`amp-${index}`)); // 80% to 120% of base sway
  
  // Randomize start position slightly so they don't emerge from the exact same pixel
  const startOffsetX = (random(`offX-${index}`) - 0.5) * 80;
  const startOffsetY = (random(`offY-${index}`) - 0.5) * 80;

  const originX = (startX / 100) * width + startOffsetX;
  const originY = (startY / 100) * height + startOffsetY;

  // The Z moves upwards a significant portion of the screen over its life
  const endY = originY - height * 0.5 - (random(`endY-${index}`) * height * 0.2);

  const easeProgress = interpolate(progress, [0, 1], [0, 1], {
    easing: Easing.out(Easing.quad), // Smooth out upward movement
  });

  const currentY = interpolate(easeProgress, [0, 1], [originY, endY]);

  // Sway horizontally using a sine wave to simulate a floating leaf or bubble
  const directionX = random(`dir-${index}`) > 0.5 ? 1 : -1;
  const currentX = originX + Math.sin(easeProgress * Math.PI * 2 * swayFreq) * swayAmp * directionX;

  // Scale: Zs start small near the "mouth", grow rapidly, and stabilize slightly larger
  const scale = interpolate(progress, [0, 0.2, 0.8, 1], [0.2, 0.9, 1.2, 1.3], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  // Opacity: Fade in quickly, hold, and fade out at the very end
  const opacity = interpolate(progress, [0, 0.1, 0.7, 1], [0, 1, 1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Wobbly rotation
  const rotation = Math.sin(easeProgress * Math.PI * 2 * swayFreq * 1.5) * 20;

  // Generate 3D shadow extrusion stacking technique
  // Adding a subtle soft drop shadow at the end enhances the floating 3D illusion
  const shadow = [
    ...Array.from({ length: Math.max(1, depth) }).map(
      (_, i) => `${i + 1}px ${i + 1}px 0px ${shadowColor}`
    ),
    `${depth + 5}px ${depth + 5}px 15px rgba(0,0,0,0.1)`
  ].join(", ");

  return (
    <div
      style={{
        position: "absolute",
        left: currentX,
        top: currentY,
        transform: `translate(-50%, -50%) scale(${scale}) rotate(${rotation}deg)`,
        opacity,
        fontFamily: paytoneFamily,
        fontSize: baseSize,
        color: zColor,
        textShadow: shadow,
        fontWeight: "bold",
        lineHeight: 1,
        transition: "none",
        margin: 0,
        padding: 0,
        zIndex: index, 
      }}
    >
      Z
    </div>
  );
};

const Sleep3DZs: React.FC<Sleep3DZsProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 8,
  zColor = "#ffffff",
  shadowColor = "#e2e8f0", // Light slate-gray acts as realistic 3D shading for an "all white" object
  baseSize = 120,
  startX = 50,
  startY = 70,
  zsPerSecond = 1.2,
  zLifespanInSeconds = 3.5,
  swayAmount = 140,
  depth = 15,
}) => {
  const { fps, durationInFrames } = useVideoConfig();

  // Handle transparency
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Calculate the timing for spawning Zs
  const lifespanFrames = Math.round(zLifespanInSeconds * fps);
  const spawnInterval = fps / zsPerSecond;
  
  // Determine how many total Zs will be generated over the full composition length
  const totalZs = Math.ceil((durationInFrames + lifespanFrames) / spawnInterval);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      {Array.from({ length: totalZs }).map((_, i) => {
        const delay = Math.round(i * spawnInterval);
        return (
          <SingleZ
            key={i}
            index={i}
            delay={delay}
            lifespan={lifespanFrames}
            zColor={zColor}
            shadowColor={shadowColor}
            baseSize={baseSize}
            startX={startX}
            startY={startY}
            swayAmount={swayAmount}
            depth={depth}
          />
        );
      })}
    </AbsoluteFill>
  );
};

export default Sleep3DZs;